#include <stdio.h>
#include <stdlib.h>
#include <time.h>
typedef struct N{int k,h;struct N*l,*r;}N;long rotations=0;int ht(N*n){return n?n->h:0;}int mx(int a,int b){return a>b?a:b;}void fix(N*n){n->h=1+mx(ht(n->l),ht(n->r));}N*rr(N*y){N*x=y->l,*t=x->r;x->r=y;y->l=t;fix(y);fix(x);rotations++;return x;}N*rl(N*x){N*y=x->r,*t=y->l;y->l=x;x->r=t;fix(x);fix(y);rotations++;return y;}N*ins(N*n,int k){if(!n){N*x=calloc(1,sizeof *n);x->k=k;x->h=1;return x;}if(k<n->k)n->l=ins(n->l,k);else if(k>n->k)n->r=ins(n->r,k);else return n;fix(n);int b=ht(n->l)-ht(n->r);if(b>1&&k<n->l->k)return rr(n);if(b< -1&&k>n->r->k)return rl(n);if(b>1){n->l=rl(n->l);return rr(n);}if(b< -1){n->r=rr(n->r);return rl(n);}return n;}int valid(N*n){if(!n)return 1;int b=ht(n->l)-ht(n->r);return b>=-1&&b<=1&&valid(n->l)&&valid(n->r);}void pre(N*n){if(n){printf("%d ",n->k);pre(n->l);pre(n->r);}}void freeall(N*n){if(n){freeall(n->l);freeall(n->r);free(n);}}
int main(void){int a[]={10,20,30,40,50,25};N*r=NULL;for(int i=0;i<6;i++){r=ins(r,a[i]);printf("after insert %d: ",a[i]);pre(r);puts("");}printf("AVL preorder: ");pre(r);printf("\nheight=%d, balance verification=%s\n",ht(r),valid(r)?"PASS":"FAIL");freeall(r);r=NULL;rotations=0;clock_t st=clock();for(int i=1;i<=100000;i++)r=ins(r,i);double elapsed=(double)(clock()-st)/CLOCKS_PER_SEC;printf("100000 sorted keys: AVL height=%d, rotations=%ld, valid=%s, insert CPU time=%.6f s\n",ht(r),rotations,valid(r)?"PASS":"FAIL",elapsed);st=clock();volatile N*x=r;for(int i=0;i<100000;i++){int k=(i*7919)%100000+1;N*p=r;while(p&&p->k!=k)p=k<p->k?p->l:p->r;x=p;}printf("100000 searches CPU time=%.6f s\n",(double)(clock()-st)/CLOCKS_PER_SEC);freeall(r);return 0;}
